export function isDocumentDateProperty(value) {
  return !(!["created","modified","lastPrinted"].includes(value));
}

export function isValidDocumentPropertyDate(value) {
  return !(!Number.isFinite(Date.prototype.getTime.call(value)));
}

export function isBiffDateProperty(value) {
  return !(!["EditTime","CreatedDate","ModifiedDate","LastPrinted"].includes(value));
}

export function isBiffListProperty(value) {
  return !(!["SheetNames","DefinedNames","ChartNames"].includes(value));
}

export function isBiffDerivedProperty(value) {
  return !(!["SystemIdentifier","CodePage","FMTID","Thumbnail","DigSig","Worksheets","SheetNames","NamedRanges","DefinedNames","Chartsheets","ChartNames","HeadingPairs","TitlesOfParts","_PID_LINKBASE","_PID_HLINKS"].includes(value));
}

export function isXlsbDerivedProperty(value) {
  return !(!["Application","AppVersion","DocSecurity","HyperlinksChanged","SharedDoc","LinksUpToDate","ScaleCrop","Worksheets","SheetNames","NamedRanges","DefinedNames","Chartsheets","ChartNames"].includes(value));
}

export function xlsxWriteSettings(options, settings, allowOmission = true) {
  if (options && Object.hasOwn(options, "cellStyles")) {
    settings.cellStyles = data(options, "cellStyles");
    if (settings.cellStyles !== undefined && typeof settings.cellStyles !== 'boolean') {
      throw failure('UNSUPPORTED_OPTIONS', "Expected a boolean cellStyles option");
    }
  }
  if (options && Object.hasOwn(options, "sheetStubs")) {
    settings.sheetStubs = data(options, "sheetStubs");
    if (settings.sheetStubs !== undefined && typeof settings.sheetStubs !== 'boolean') {
      throw failure('UNSUPPORTED_OPTIONS', "Expected a boolean sheetStubs option");
    }
  }
  if (options && Object.hasOwn(options, "compression")) {
    settings.compression = data(options, "compression");
    if (settings.compression !== undefined && typeof settings.compression !== 'boolean') {
      throw failure('UNSUPPORTED_OPTIONS', "Expected a boolean compression option");
    }
  }
  if (options && Object.hasOwn(options, "ignoreEC")) {
    settings.ignoreEC = data(options, "ignoreEC");
    if (settings.ignoreEC !== undefined && typeof settings.ignoreEC !== 'boolean') {
      throw failure('UNSUPPORTED_OPTIONS', "Expected a boolean ignoreEC option");
    }
  }
  if (options && Object.hasOwn(options, "bookSST")) {
    settings.bookSST = data(options, "bookSST");
    if (settings.bookSST !== undefined && typeof settings.bookSST !== 'boolean') {
      throw failure('UNSUPPORTED_OPTIONS', "Expected a boolean bookSST option");
    }
  }
  if (options && Object.hasOwn(options, "cellDates")) {
    settings.cellDates = data(options, "cellDates");
    if (settings.cellDates !== undefined && typeof settings.cellDates !== 'boolean') {
      throw failure('UNSUPPORTED_OPTIONS', "Expected a boolean cellDates option");
    }
  }
  if (options && Object.hasOwn(options, "themeXLSX")) {
    settings.themeXLSX = data(options, "themeXLSX");
    if (settings.themeXLSX !== undefined && typeof settings.themeXLSX !== 'string') {
      throw failure('UNSUPPORTED_OPTIONS', "Expected a themeXLSX XML string");
    }
  }
  if (options && Object.hasOwn(options, "codepage")) {
    settings.codepage = data(options, "codepage");
    if (settings.codepage !== undefined && (!Number.isInteger(settings.codepage) || settings.codepage < 0)) {
      throw failure('UNSUPPORTED_OPTIONS', "Expected a nonnegative integer codepage");
    }
  }
  if (options && Object.hasOwn(options, "Props")) {
    settings.Props = data(options, "Props");
  }
  if (options && Object.hasOwn(options, "sheet")) {
    settings.sheet = data(options, "sheet");
  }
  if (options && Object.hasOwn(options, "WTF")) {
    settings.WTF = data(options, "WTF");
  }
  if (options && Object.hasOwn(options, "numbers")) {
    settings.numbers = data(options, "numbers");
  }
  if (options && Object.hasOwn(options, "bookVBA")) {
    settings.bookVBA = data(options, "bookVBA");
  }
  if (options && Object.hasOwn(options, "FS")) {
    settings.FS = data(options, "FS");
  }
  if (options && Object.hasOwn(options, "RS")) {
    settings.RS = data(options, "RS");
  }
  optionsMatch(options, settings, allowOmission);
  return settings;
}

export function odsWriteSettings(options, settings) {
  collect(options, ["compression","sheet","bookSST","cellDates","Props","cellStyles","sheetStubs","ignoreEC","themeXLSX","WTF","numbers","codepage","bookVBA","FS","RS"], settings);
  optionsMatch(options, settings);
  if (settings.compression !== undefined && typeof settings.compression !== 'boolean') {
    throw failure('UNSUPPORTED_OPTIONS', "Expected a boolean compression option");
  }
  return settings;
}

