export function xlmlStreamSettings(options) {
  const {
    stride,
  } = options ?? {};
  if (stride != null && (!Number.isSafeInteger(stride) || stride < 0)) throw failure("INVALID_VALUE", "Expected a nonnegative SpreadsheetML row stride");
  return { stride: stride ?? 10 };
}

